CREATE OR REFRESH MATERIALIZED VIEW gold.daily_revenue (
  order_date DATE NOT NULL COMMENT 'Date the orders were placed (UTC)',
  country_code STRING NOT NULL COMMENT 'ISO 3166-1 alpha-2 delivery country',
  orders_count BIGINT NOT NULL COMMENT 'Number of orders placed, including cancelled ones',
  cancelled_count BIGINT NOT NULL COMMENT 'Number of cancelled orders',
  revenue_eur DECIMAL(18,2) NOT NULL COMMENT 'Revenue of non-cancelled orders, EUR incl. VAT',
  avg_order_value_eur DECIMAL(18,2) COMMENT 'Average value of non-cancelled orders, EUR',
  latest_ingested_at TIMESTAMP NOT NULL COMMENT 'Most recent ingestion time of the orders behind this row; drives the freshness SLA',
  CONSTRAINT order_date_required EXPECT (coalesce((order_date IS NOT NULL), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT country_code_required EXPECT (coalesce((country_code IS NOT NULL), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT orders_count_required EXPECT (coalesce((orders_count IS NOT NULL), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT orders_count_positive EXPECT (coalesce((orders_count > 0), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT cancelled_count_required EXPECT (coalesce((cancelled_count IS NOT NULL), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT revenue_eur_required EXPECT (coalesce((revenue_eur IS NOT NULL), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT revenue_non_negative EXPECT (coalesce((revenue_eur >= 0), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT avg_order_value_plausible EXPECT (coalesce((avg_order_value_eur IS NULL OR avg_order_value_eur < 5000), false)),
  CONSTRAINT latest_ingested_at_required EXPECT (coalesce((latest_ingested_at IS NOT NULL), false)) ON VIOLATION FAIL UPDATE,
  CONSTRAINT daily_revenue_pk PRIMARY KEY (order_date, country_code)
)
COMMENT 'Daily revenue and order counts per delivery country, excluding cancelled orders from revenue. Usage: Sales dashboards and country performance reviews. Row access is limited to the countries a consumer is entitled to (governance.country_access). Limitations: Revenue is gross (incl. VAT) in EUR. Late-arriving orders are included on their order date. Owner: Sales Analytics. Contract urn:datacontract:sales:daily_revenue v1.0.0.'
TBLPROPERTIES (
  'contract.id' = 'urn:datacontract:sales:daily_revenue',
  'contract.version' = '1.0.0',
  'contract.status' = 'active',
  'contract.owner_team' = 'Sales Analytics',
  'contract.source' = 'data_products/sales/daily_revenue/daily_revenue.odcs.yaml',
  'contract.table_role' = 'product'
)
WITH ROW FILTER ${contracts.catalog}.governance.filter_country ON (country_code)
AS
-- ── business logic: data_products/sales/daily_revenue/daily_revenue.logic.sql ──
-- Business logic of the daily_revenue data product: a plain SELECT, nothing else.
-- contractctl wraps it with the schema, expectations, row filter, comments and
-- properties promised in daily_revenue.odcs.yaml. Read only from declared inputs.
SELECT
  CAST(order_ts AS DATE)                                                    AS order_date,
  country_code,
  COUNT(*)                                                                  AS orders_count,
  COUNT_IF(order_status = 'CANCELLED')                                      AS cancelled_count,
  CAST(SUM(CASE WHEN order_status <> 'CANCELLED' THEN amount ELSE 0 END)
       AS DECIMAL(18,2))                                                    AS revenue_eur,
  CAST(SUM(CASE WHEN order_status <> 'CANCELLED' THEN amount END)
       / NULLIF(COUNT_IF(order_status <> 'CANCELLED'), 0) AS DECIMAL(18,2)) AS avg_order_value_eur,
  MAX(ingested_at)                                                          AS latest_ingested_at
FROM silver.orders
GROUP BY CAST(order_ts AS DATE), country_code;
